// BAD: Improper Java API usage leading to SQL Injection (vulnerable)
// Example: A servlet handling a login request using string concatenation to build SQL
import java.io.IOException;
import java.sql.*;
import javax.servlet.ServletException;
import javax.servlet.annotation.WebServlet;
import javax.servlet.http.*;

@WebServlet("/login")
public class LoginServletBad extends HttpServlet {
    private static final String JDBC_URL = "jdbc:mysql://localhost:3306/appdb";
    private static final String JDBC_USER = "appuser";
    private static final String JDBC_PASS = "apppass";

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String username = req.getParameter("username"); // untrusted input
        String password = req.getParameter("password"); // untrusted input

        // vulnerable: direct string concatenation allows SQL Injection
        String sql = "SELECT id, username FROM users WHERE username = '" + username +
                     "' AND password_hash = SHA2('" + password + "', 256)";

        try (Connection conn = DriverManager.getConnection(JDBC_URL, JDBC_USER, JDBC_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(sql)) {

            if (rs.next()) {
                // BAD: Sets a session attribute without additional security flags or checks
                HttpSession session = req.getSession();
                session.setAttribute("userId", rs.getInt("id"));
                resp.sendRedirect("/home");
            } else {
                resp.sendError(HttpServletResponse.SC_UNAUTHORIZED, "Invalid credentials");
            }
        } catch (SQLException e) {
            // BAD: Leaks internal SQL details to the client
            resp.sendError(HttpServletResponse.SC_INTERNAL_SERVER_ERROR, "DB error: " + e.getMessage());
        }
    }
}
***
/**
 * GOOD: Safe Java API usage with parameterized queries and secure session/cookie handling
 * Fixes:
 * - Use PreparedStatement to prevent SQL Injection
 * - Use constant-time password verification with bcrypt/argon2 (example shows bcrypt)
 * - Avoid leaking internal errors
 * - Set secure session cookie attributes
 */
import java.io.IOException;
import java.sql.*;
import javax.servlet.ServletException;
import javax.servlet.annotation.WebServlet;
import javax.servlet.http.*;
import org.mindrot.jbcrypt.BCrypt; // e.g., jBCrypt library

@WebServlet("/login")
public class LoginServletGood extends HttpServlet {
    private static final String JDBC_URL = "jdbc:mysql://localhost:3306/appdb";
    private static final String JDBC_USER = "appuser";
    private static final String JDBC_PASS = "apppass";

    @Override
    public void init() {
        // Ensure session cookies are secure (if server/container allows programmatic control)
        // Some containers derive these from deployment descriptors; shown here for clarity.
        HttpSessionCookieConfig cfg = getServletContext().getSessionCookieConfig();
        cfg.setHttpOnly(true);
        cfg.setSecure(true);
        cfg.setName("SESSIONID");
        cfg.setPath("/");
        cfg.setSameSite("Lax"); // use "Strict" if appropriate
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String username = safeTrim(req.getParameter("username"));
        String password = req.getParameter("password");

        if (username == null || password == null || username.length() > 128 || password.length() > 1024) {
            resp.sendError(HttpServletResponse.SC_BAD_REQUEST, "Invalid input");
            return;
        }

        String sql = "SELECT id, username, password_hash FROM users WHERE username = ?";

        try (Connection conn = DriverManager.getConnection(JDBC_URL, JDBC_USER, JDBC_PASS);
             PreparedStatement ps = conn.prepareStatement(sql)) {

            // FIX: Parameterized query prevents SQL Injection
            ps.setString(1, username);

            try (ResultSet rs = ps.executeQuery()) {
                if (!rs.next()) {
                    // Generic error to avoid user enumeration
                    sendAuthFailed(resp);
                    return;
                }

                int userId = rs.getInt("id");
                String storedHash = rs.getString("password_hash");

                // FIX: Use a strong password hashing function; verify in constant time
                boolean ok = storedHash != null && BCrypt.checkpw(password, storedHash);

                if (ok) {
                    // Rotate session to prevent fixation
                    HttpSession old = req.getSession(false);
                    if (old != null) old.invalidate();
                    HttpSession session = req.getSession(true);
                    session.setAttribute("userId", userId);
                    // Optionally set session timeout
                    session.setMaxInactiveInterval(30 * 60);
                    resp.sendRedirect("/home");
                } else {
                    sendAuthFailed(resp);
                }
            }
        } catch (SQLException e) {
            // FIX: Log internally, return generic error to client
            log("Database error during login", e);
            resp.sendError(HttpServletResponse.SC_INTERNAL_SERVER_ERROR, "Unexpected error");
        }
    }

    private static String safeTrim(String s) {
        if (s == null) return null;
        String t = s.trim();
        return t.isEmpty() ? null : t;
    }

    private void sendAuthFailed(HttpServletResponse resp) throws IOException {
        resp.setStatus(HttpServletResponse.SC_UNAUTHORIZED);
        resp.getWriter().write("Invalid credentials");
    }
}

