// BAD: Demonstrates improper Java API use leading to vulnerabilities
// Scenario: SQL injection via String concatenation and insecure deserialization over HTTP
import java.io.*;
import java.net.*;
import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;

public class InsecureServlet extends HttpServlet {
    private Connection getConnection() throws Exception {
        // Hardcoded credentials and no TLS verification (bad practice)
        return DriverManager.getConnection("jdbc:mysql://localhost:3306/appdb", "appuser", "apppass");
    }

    protected void doPost(HttpServletRequest req, HttpServletResponse resp) throws IOException {
        String username = req.getParameter("username");
        String password = req.getParameter("password");

        try (Connection conn = getConnection();
             Statement stmt = conn.createStatement()) {

            // vulnerable: SQL injection via string concatenation
            String sql = "SELECT * FROM users WHERE username='" + username + "' AND password='" + password + "'";
            ResultSet rs = stmt.executeQuery(sql);

            if (rs.next()) {
                resp.getWriter().println("Welcome " + rs.getString("username"));
            } else {
                resp.getWriter().println("Invalid credentials");
            }
        } catch (Exception e) {
            resp.sendError(500);
        }

        // Insecure deserialization from untrusted source over HTTP (no validation)
        String url = req.getParameter("profileUrl");
        if (url != null) {
            try (InputStream is = new URL(url).openStream();
                 ObjectInputStream ois = new ObjectInputStream(is)) {
                // vulnerable: Untrusted deserialization can lead to RCE if gadget chains exist
                Object profile = ois.readObject();
                resp.getWriter().println("Loaded profile: " + profile.toString());
            } catch (Exception e) {
                resp.getWriter().println("Error loading profile");
            }
        }
    }
}
***
/*
GOOD: Fixes
- Use PreparedStatement with parameters to prevent SQL injection.
- Use password hashing verification (e.g., BCrypt) instead of comparing plaintext.
- Avoid untrusted deserialization; use JSON with strict schema validation and safe parsing.
- Validate and whitelist URLs if remote fetching is truly needed, and use timeouts.
*/
import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.util.*;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.databind.exc.MismatchedInputException;
import org.mindrot.jbcrypt.BCrypt;

public class SecureServlet extends HttpServlet {
    private static final Set<String> ALLOWED_PROFILE_HOSTS = Set.of("profiles.example.com");
    private static final ObjectMapper MAPPER = new ObjectMapper();

    private Connection getConnection() throws Exception {
        // Use proper secrets management in real apps; ensure TLS and cert validation in JDBC URL
        // Example: jdbc:mysql://localhost:3306/appdb?useSSL=true&requireSSL=true&verifyServerCertificate=true
        return DriverManager.getConnection("jdbc:mysql://localhost:3306/appdb", "appuser", "apppass");
    }

    protected void doPost(HttpServletRequest req, HttpServletResponse resp) throws IOException {
        String username = req.getParameter("username");
        String password = req.getParameter("password");

        try (Connection conn = getConnection();
             PreparedStatement ps = conn.prepareStatement(
                     "SELECT username, password_hash FROM users WHERE username = ?")) { // Parameterized query blocks injection

            ps.setString(1, username);
            try (ResultSet rs = ps.executeQuery()) {
                if (rs.next()) {
                    String storedHash = rs.getString("password_hash");
                    // Compare using a slow hash like BCrypt/Argon2/PBKDF2
                    if (storedHash != null && BCrypt.checkpw(password, storedHash)) {
                        resp.getWriter().println("Welcome " + rs.getString("username"));
                    } else {
                        resp.getWriter().println("Invalid credentials");
                    }
                } else {
                    resp.getWriter().println("Invalid credentials");
                }
            }
        } catch (SQLException e) {
            // Log securely; avoid leaking details
            resp.sendError(500);
            return;
        }

        // Safe alternative: fetch JSON and parse into a strict DTO instead of deserializing Java objects
        String urlParam = req.getParameter("profileUrl");
        if (urlParam != null) {
            try {
                URL url = new URL(urlParam);
                // Whitelist hostnames to prevent SSRF
                if (!ALLOWED_PROFILE_HOSTS.contains(url.getHost())) {
                    resp.getWriter().println("Profile host not allowed");
                    return;
                }

                URLConnection conn = url.openConnection();
                conn.setConnectTimeout(3000);
                conn.setReadTimeout(3000);

                try (InputStream is = conn.getInputStream()) {
                    // Expect JSON, not serialized Java; map to a strict POJO
                    UserProfile profile = MAPPER.readValue(is, UserProfile.class);
                    resp.getWriter().println("Loaded profile: " + profile.username);
                }
            } catch (MismatchedInputException | JsonProcessingException e) {
                resp.getWriter().println("Invalid profile format");
            } catch (Exception e) {
                resp.getWriter().println("Error loading profile");
            }
        }
    }

    // Strict DTO with explicit fields; no code execution during construction
    public static class UserProfile {
        public String username;
        public String displayName;
        public String bio;

        // Optionally add validation logic
        public void validate() {
            if (username == null || username.length() > 32) throw new IllegalArgumentException("Invalid username");
        }
    }
}

