{
  "title": "Software Engineer Performance Review Rubric",
  "version": "1.0",
  "sections": [
    {
      "category": "Technical Excellence",
      "weight": 0.25,
      "criteria": [
        {
          "name": "Code Quality",
          "description": "Writes clean, maintainable, and idiomatic code with appropriate abstractions and tests.",
          "levels": {
            "1": "Frequent defects, inconsistent style, minimal tests, unclear structure.",
            "2": "Basic correctness; occasional defects; limited tests; some refactoring needed.",
            "3": "Consistently readable and correct code; good test coverage; thoughtful design.",
            "4": "High-quality, well-factored code; strong tests; proactively improves codebase.",
            "5": "Sets org-wide quality bar; creates reusable patterns; mentors others on craftsmanship."
          }
        },
        {
          "name": "System Design",
          "description": "Designs components/services with scalability, reliability, and simplicity in mind.",
          "levels": {
            "1": "Struggles to decompose problems; overlooks trade-offs.",
            "2": "Designs small components; limited consideration of non-functional requirements.",
            "3": "Designs well-scoped services; justifies trade-offs; uses appropriate patterns.",
            "4": "Architects cross-team systems; anticipates growth/failure modes; documents clearly.",
            "5": "Drives architecture strategy; influences standards; conducts high-quality design reviews."
          }
        },
        {
          "name": "Debugging and Problem Solving",
          "description": "Efficiently diagnoses and resolves issues using data and systematic methods.",
          "levels": {
            "1": "Slow to isolate issues; relies heavily on others.",
            "2": "Resolves straightforward bugs; limited root-cause analysis.",
            "3": "Quickly identifies root causes; proposes durable fixes; uses observability tools.",
            "4": "Resolves complex, ambiguous issues; improves diagnostics and tooling.",
            "5": "Preempts classes of issues; institutionalizes best practices for problem solving."
          }
        }
      ]
    },
    {
      "category": "Execution and Delivery",
      "weight": 0.25,
      "criteria": [
        {
          "name": "Planning and Estimation",
          "description": "Breaks work into milestones, estimates realistically, and manages risk.",
          "levels": {
            "1": "Weak estimates; misses deadlines; unclear scope.",
            "2": "Basic task breakdown; estimates vary; limited risk mitigation.",
            "3": "Reliable plans; proactive risk tracking; communicates changes.",
            "4": "Coordinates multi-team plans; de-risks with spikes; adapts quickly.",
            "5": "Sets execution patterns; mentors others in project planning and delivery."
          }
        },
        {
          "name": "Ownership and Accountability",
          "description": "Owns outcomes end-to-end and upholds commitments.",
          "levels": {
            "1": "Requires close guidance; drops tasks or context.",
            "2": "Owns assigned tasks; needs reminders for follow-through.",
            "3": "Owns features/services; ensures quality and support readiness.",
            "4": "Owns mission-critical areas; drives cross-functional outcomes.",
            "5": "Acts as product/technical owner for domains; accountable for business impact."
          }
        },
        {
          "name": "Operational Excellence",
          "description": "Builds reliable systems with strong SLAs, observability, and response practices.",
          "levels": {
            "1": "Introduces avoidable instability; limited monitoring.",
            "2": "Responds to incidents; adds basic metrics/logging.",
            "3": "Implements robust alerting, runbooks, and SLOs; reduces toil.",
            "4": "Leads incident response/postmortems; drives systemic reliability improvements.",
            "5": "Defines operational standards; measurably improves org-wide reliability."
          }
        }
      ]
    },
    {
      "category": "Collaboration and Communication",
      "weight": 0.2,
      "criteria": [
        {
          "name": "Teamwork",
          "description": "Contributes positively to team dynamics and shared goals.",
          "levels": {
            "1": "Silos information; difficult to collaborate.",
            "2": "Collaborates when prompted; limited knowledge sharing.",
            "3": "Proactively supports peers; shares context and best practices.",
            "4": "Facilitates effective collaboration across teams; resolves conflicts constructively.",
            "5": "Builds strong networks; elevates team effectiveness and culture."
          }
        },
        {
          "name": "Communication",
          "description": "Communicates clearly, concisely, and with appropriate detail for the audience.",
          "levels": {
            "1": "Unclear updates; missing context; weak documentation.",
            "2": "Basic updates; documentation needs guidance.",
            "3": "Clear written/verbal updates; solid docs; adapts to audience.",
            "4": "Influences decisions with crisp communication; exemplary documentation.",
            "5": "Org-level communicator; clarifies ambiguity; sets documentation standards."
          }
        },
        {
          "name": "Code Review and Feedback",
          "description": "Gives and receives feedback constructively; improves team quality.",
          "levels": {
            "1": "Surface-level or unconstructive reviews; resists feedback.",
            "2": "Identifies obvious issues; feedback sometimes unclear.",
            "3": "Thoughtful, respectful reviews; receptive to feedback.",
            "4": "Raises team bar; mentors through reviews; balances velocity and quality.",
            "5": "Shapes review culture; teaches systemic improvements; prevents recurring issues."
          }
        }
      ]
    },
    {
      "category": "Impact and Innovation",
