            "5": "Org-wide leadership; builds programs that scale mentorship and excellence."
          }
        }
      ]
    }
  ],
  "scoring": {
    "scale": {
      "1": "Below Expectations",
      "2": "Developing",
      "3": "Meets Expectations",
      "4": "Exceeds Expectations",
      "5": "Outstanding"
